import {ecomPathname, getApiHeaders} from '../utils/api-endpoint';

type FetchDeleteGarageOptions = {
  baseSiteId: string;
  apiEndpoint: string;
  userId: string;
  ecomAccessToken: string;
  idToken: string;
  accessToken: string;
  language: string;
  productId: string;
  customerId?: string;
  salesChannel?: string;
};

export async function fetchDeleteGarage({
  baseSiteId,
  apiEndpoint,
  userId,
  ecomAccessToken,
  idToken,
  accessToken,
  language,
  productId,
  customerId,
  salesChannel,
}: FetchDeleteGarageOptions): Promise<any> {
  const apiHeaders = getApiHeaders();

  const signalHeaders: Record<string, string> = {
    ...apiHeaders,
    [`base-site-id`]: baseSiteId,
    [`ecomm-access-token`]: ecomAccessToken,
    [`user-id`]: userId,
    [`id-token`]: idToken,
    [`access-token`]: accessToken,
  };

  if (salesChannel) {
    signalHeaders[`x-channel`] = salesChannel;
  }

  if (customerId) {
    signalHeaders[`customer-id`] = customerId;
  }

  const signal = {method: `DELETE`, headers: signalHeaders};

  const queryParams = new URLSearchParams({
    lang: language,
    fields: `DEFAULT`,
    pn18: productId,
  });

  const url = `${apiEndpoint}${ecomPathname}/garage?${queryParams.toString()}`;

  const response = await fetch(url, signal);

  if (!response.ok) {
    throw new Error(
      `AWS API returned ${response.status} - ${response.statusText}`,
    );
  }

  return response.json();
}

import {parseAdbContextCookie, parseLoginUserDetailsCookie} from '@smart/utils';
import type {APIGatewayProxyHandler, APIGatewayProxyResult} from 'aws-lambda';
import {adbSalesChannel} from '../config';
import type {ChangeGarageResponse} from '../types';
import {getApiEndpoint} from '../utils/api-endpoint';
import {fetchDeleteGarage} from './fetch-delete-garage';
import {queryParamsSchema} from './query-params';

export const handler: APIGatewayProxyHandler = async (
  event,
): Promise<APIGatewayProxyResult> => {
  const queryParams = queryParamsSchema.safeParse(
    event.queryStringParameters || {},
  );

  if (!queryParams.success) {
    return {statusCode: 400, body: JSON.stringify(queryParams.error)};
  }
  const {envName, marketId, language, productId} = queryParams.data;

  const baseSiteId = `smart-${marketId.toLowerCase()}`;

  try {
    const apiEndpoint = getApiEndpoint(envName);
    const cookie = event.headers.Cookie ?? event.headers.cookie ?? ``;
    const adbContext = parseAdbContextCookie(cookie);
    const userDetails = parseLoginUserDetailsCookie(cookie);

    const salesChannel = adbContext?.customerUserId && adbSalesChannel;

    if (!userDetails?.userId || !userDetails?.ecomAccessToken) {
      return {statusCode: 401, body: `Unauthorized - User is not logged in`};
    }

    const response = await fetchDeleteGarage({
      baseSiteId,
      apiEndpoint,
      userId: userDetails.userId,
      ecomAccessToken: userDetails.ecomAccessToken,
      idToken: userDetails.idToken,
      accessToken: userDetails.accessToken,
      language,
      productId,
      customerId: adbContext?.customerUserId,
      salesChannel,
    });
    const productInGarage = response?.[`response-data`]?.output?.product;
    const isProductInGarage = Boolean(productInGarage?.code === productId);
    const changeGarageResponse: ChangeGarageResponse = {
      productId,
      isProductInGarage,
    };

    return {
      statusCode: 200,
      body: JSON.stringify(changeGarageResponse),
      headers: {
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
    };
  } catch (error) {
    console.error(error);

    return {statusCode: 500, body: `500 - Server Error`};
  }
};

