import {MulesoftClient, createBaseSiteId} from '@smart/api-clients';
import {parseAdbContextCookie, parseLoginUserDetailsCookie} from '@smart/utils';
import type {APIGatewayProxyHandler, APIGatewayProxyResult} from 'aws-lambda';
import {adbSalesChannel} from '../config';
import {fetchProduct} from '../fetch-product';
import type {GarageItem, MuleSoftProduct} from '../types';
import {ecomPathname, getApiEndpoint} from '../utils/api-endpoint';
import {createGarageModel} from './create-garage-model';
import {fetchGetGarage} from './fetch-get-garage';
import {queryParamsSchema} from './query-params';

export const handler: APIGatewayProxyHandler = async (
  event,
): Promise<APIGatewayProxyResult> => {
  const queryParams = queryParamsSchema.safeParse(
    event.queryStringParameters || {},
  );
  if (!queryParams.success) {
    return {statusCode: 400, body: JSON.stringify(queryParams.error)};
  }
  const {
    envName,
    marketId,
    language,
    preview,
    duration,
    mileage,
    advancePayment,
    advanceMonth,
    salesType,
  } = queryParams.data;

  const baseSiteId = `smart-${marketId.toLowerCase()}`;

  try {
    const apiEndpoint = getApiEndpoint(envName);

    const cookie = event.headers.Cookie ?? event.headers.cookie ?? ``;
    const adbContext = parseAdbContextCookie(cookie);
    const userDetails = parseLoginUserDetailsCookie(cookie);

    const salesChannel = adbContext?.customerUserId && adbSalesChannel;

    if (!userDetails?.userId || !userDetails?.ecomAccessToken) {
      throw new Error(`User is not logged in`);
    }

    const garage = await fetchGetGarage({
      baseSiteId,
      apiEndpoint,
      userId: userDetails.userId,
      ecomAccessToken: userDetails.ecomAccessToken,
      idToken: userDetails.idToken,
      accessToken: userDetails.accessToken,
      language,
      customerId: adbContext?.customerUserId,
      salesChannel,
    });

    const productsInGarage: GarageItem[] =
      garage?.[`response-data`]?.entries || [];

    const products: MuleSoftProduct[] = (
      await Promise.all(
        productsInGarage
          .filter((product) => product?.product?.code)
          .map(async (product) =>
            fetchProduct({
              baseSiteId,
              apiEndpoint,
              language,
              productId: `${product.product?.code}`,
            }),
          ),
      )
    ).map((product) => product[`response-data`] as MuleSoftProduct);

    const hasPaymentConfig =
      (advancePayment || advanceMonth) && duration && mileage;
    let productDetailPrices;
    const awsEndpoint = `${apiEndpoint}${ecomPathname}`;
    if (hasPaymentConfig) {
      const client = new MulesoftClient({
        endpoint: {
          origin: awsEndpoint,
          authorizationHeaders: {
            'x-api-key': process.env.X_API_KEY || ``,
            'base-site-id': baseSiteId,
          },
        },
      });
      productDetailPrices = await client.fetchProductPrices({
        advancePayment,
        advanceMonth,
        duration,
        mileage,
        products: productsInGarage.map(
          (product) => product.product?.code,
        ) as string[],
        baseSiteId: createBaseSiteId(marketId),
        language,
        salesType,
      });
    }
    const garageModel = createGarageModel(
      products,
      {envName, preview},
      productDetailPrices?.prices,
    );

    // Default return, also if fetch with user details fails
    return {
      statusCode: 200,
      body: JSON.stringify(garageModel),
      headers: {
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
    };
  } catch (error) {
    console.error(error);

    return {statusCode: 500, body: `500 - Server Error`};
  }
};

